from collections import defaultdict
def comps(g,col):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ inrange(H)]
    o=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                o.append(c)
    return o
